import{_ as e,o as a,c as n,a2 as r}from"./chunks/framework.BjkiRu3Q.js";const u=JSON.parse('{"title":"Company onboarding","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/company-onboarding.md","filePath":"getting-started/company-onboarding.md"}'),i={name:"getting-started/company-onboarding.md"};function o(d,t,s,c,l,p){return a(),n("div",null,[...t[0]||(t[0]=[r('<h1 id="company-onboarding" tabindex="-1">Company onboarding <a class="header-anchor" href="#company-onboarding" aria-label="Permalink to &quot;Company onboarding&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">Reference release</p><p>Operational guidance reviewed against v0.7.26. Verify the installed release, permissions and approved scope. Training uses authorized synthetic data; this guide does not authorize commercial activation.</p></div><h2 id="prepare-the-tenant" tabindex="-1">Prepare the tenant <a class="header-anchor" href="#prepare-the-tenant" aria-label="Permalink to &quot;Prepare the tenant&quot;">​</a></h2><p>Confirm the approved installed release, authorized administrator and support owner. Open Company Settings and review the company onboarding checklist. The v0.7.26 source checks eight required configuration areas:</p><table tabindex="0"><thead><tr><th>Area</th><th>Checklist criterion</th><th>Verify independently</th></tr></thead><tbody><tr><td>Company identity</td><td>Trading name, legal entity, tax/VAT identifier</td><td>Accuracy with authorized company records</td></tr><tr><td>Markets</td><td>At least one active market</td><td>Correct time zone and actual service coverage</td></tr><tr><td>Locations</td><td>At least two non-disabled locations</td><td>Valid route endpoints in each intended market</td></tr><tr><td>Fleet</td><td>At least one class and non-archived vehicle</td><td>Capacity, availability, maintenance</td></tr><tr><td>Chauffeurs</td><td>At least one non-archived driver</td><td>Duty, account association and actual access</td></tr><tr><td>Pricing</td><td>Positive route/hourly rate or class multiplier</td><td>Valid quote for each sold service</td></tr><tr><td>Channels</td><td>At least one active booking channel</td><td>Domain, publication and independent intake gates</td></tr><tr><td>Settlement</td><td>Currency, time zone and buffer of at least 15 minutes</td><td>Actual payment and dispatch acceptance</td></tr></tbody></table><p>A complete configuration checklist is not operational acceptance. The location check is a count, not route coverage; class multiplier fallback does not guarantee a valid fare; a channel label does not enable public intake. The driver count does not prove a linked login. Demo readiness is not commercial readiness.</p><p>Recommended areas include hourly and seasonal rates, tours, partners, templates, branding and operator users. Expanded checklist items depend on supplied data. If operator count is unavailable, the source may infer team readiness from company identity; verify actual accounts independently.</p><h2 id="order-of-setup" tabindex="-1">Order of setup <a class="header-anchor" href="#order-of-setup" aria-label="Permalink to &quot;Order of setup&quot;">​</a></h2><p>Complete identity, markets, locations, fleet, drivers, tariffs and channels; confirm settlement policy and authorize individual accounts. Review optional services only if sold. Use synthetic records to test <a href="/getting-started/first-reservation.html">first reservation</a>, then follow the <a href="/getting-started/go-live-checklist.html">go-live checklist</a>. Keep external providers and public intake disabled unless separately approved.</p><p>See <a href="/plus/company-and-language-settings.html">Company settings</a>, <a href="/plus/staff-administration.html">Staff administration</a> and <a href="/integrations/third-party-api-setup.html">API setup</a>.</p>',10)])])}const m=e(i,[["render",o]]);export{u as __pageData,m as default};
